'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'
import { ChevronGlyph } from './glyphs'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled ChatStream, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './chat-stream.css'

// The shared rule sets, so the theme's action face and press gesture reach the
// resume control. GSUI-118: the file shipped with the tokens and nothing
// imported it, so the classes matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * ChatStream: the room, in a frame that holds still.
 *
 * Specimens 6b and 6j. The height comes from the host, the same way a `stage`
 * takes its height from the game screen around it, and the list inside is the
 * only thing that scrolls. That is the whole point: a message arriving moves
 * one column inside the frame and never the composer under the player's thumb.
 *
 * Two attributes carry the two ways a stream stops, because they are two
 * different things happening to two different people. `data-gs-following`
 * absent is the player pausing it by reading: the scroll stops and the room
 * carries on. `data-gs-paused` is the host freezing the room, which stops the
 * room. A player reading back through a room that has just been frozen has
 * both at once.
 *
 * It stores nothing, ranks nothing and screens nothing. It scrolls itself to
 * the foot while it is following, which is a fact about a scroll container
 * rather than a decision about a game, and it reports the player scrolling
 * away so the host can stop following. Every count on screen is a prop.
 *
 * `placement` is specimen 6i: the three ways chat fits a game screen while the
 * screen holds still. It is a prop rather than three components because the
 * room is the same room in all three, and it is drawn as
 * `data-gs-presentation` rather than `data-gs-placement` because the three
 * differ in what the stream contains and not only in where it sits: an
 * `overlay` has no composer and does not scroll. Where each one goes in a
 * `stage` is documented in `docs/public/stage.md`; this component is put
 * there by the host and positions nothing itself.
 */

export type ChatStreamPlacement = 'docked' | 'sheet' | 'overlay'

export interface ChatStreamProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** What the stream is, for anybody reading it out. */
  label?: string
  /**
   * The one message held at the top, usually the host's. It does not scroll
   * away, and there is one at a time: a second pinned message is a second
   * thing to read before the room.
   */
  pinned?: React.ReactNode
  /** The messages, oldest first. Newest sits at the foot, where the eye is. */
  children?: React.ReactNode

  /** Pinned to the foot, each arrival scrolling it by one. The default. */
  following?: boolean
  /** How many arrived while the player was reading. Drawn on the resume control. */
  newCount?: number
  /** The player scrolled away from the foot. The host stops following. */
  onPause?: () => void
  /** The resume control was pressed. The host starts following again. */
  onResume?: () => void
  /**
   * How many messages the player missed while they were away. One centred line
   * marks the break; the stream does not replay them and does not pretend they
   * never happened.
   */
  gap?: number

  /** The host froze the room for everybody. */
  paused?: boolean

  /**
   * How the room fits the game screen around it, specimen 6i. `sheet` is the
   * default and the one most rounds want: chat visits, over the scene, and is
   * dragged back down, which is the host wrapping this in a `sheet`. `docked`
   * is a fixed band at the foot inside the stage's interaction layer, for a
   * screen where chat is the point; note GSUI-219, because that layer is
   * capped at 40% of the stage and a docked room wants more. `overlay` floats
   * the last few messages over the scene and fades them: no composer, no
   * scroll, nothing to press.
   */
  placement?: ChatStreamPlacement
}

/** Within this many pixels of the foot still counts as being at the foot. */
const AT_FOOT = 8

export function ChatStream(props: ChatStreamProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    label = copy['chat-stream.label'],
    pinned,
    children,
    following = true,
    newCount = 0,
    onPause,
    onResume,
    gap,
    paused = false,
    placement = 'sheet',
    className,
    ...rest
  } = componentProps

  const list = React.useRef<HTMLDivElement>(null)

  // An overlay is atmosphere: the last few messages, fading, over the scene.
  // There is nothing to scroll back through and nothing to resume to, so the
  // resume control and the pause report are both off. The composer was never
  // this component's to draw.
  const atmosphere = placement === 'overlay'

  // While it is following, the foot is where the stream sits. This runs on
  // every render rather than on a message count, because the host owns the
  // children and this component cannot count them without reading into them.
  React.useEffect(() => {
    const node = list.current
    if (!node || !following) return
    node.scrollTop = node.scrollHeight
  })

  const onListScroll = React.useCallback(() => {
    const node = list.current
    if (!node || !onPause || !following || atmosphere) return
    const distance = node.scrollHeight - node.scrollTop - node.clientHeight
    if (distance > AT_FOOT) onPause()
  }, [atmosphere, following, onPause])

  return (
    <div
      {...rest}
      className={['gs-chat-stream', className].filter(Boolean).join(' ')}
      data-gs-component="chat-stream"
      data-gs-presentation={placement}
      data-gs-following={following ? 'true' : undefined}
      data-gs-paused={paused ? 'true' : undefined}
    >
      {pinned !== undefined ? (
        <div className="gs-chat-stream__pinned" data-gs-scope="chat-stream" data-gs-part="row">
          {pinned}
        </div>
      ) : null}

      <div
        ref={list}
        className="gs-chat-stream__list"
        data-gs-scope="chat-stream" data-gs-part="list"
        onScroll={onListScroll}
        // A log rather than a live region that interrupts: a room reads out in
        // order and nothing in it is urgent. A frozen room announces nothing,
        // because there is nothing arriving to announce.
        role="log"
        aria-label={paused ? copy['chat-stream.pausedLabel'](label, copy['chat-stream.paused']) : label}
        aria-live={following && !paused ? 'polite' : 'off'}
      >
        {gap !== undefined ? (
          <p className="gs-chat-stream__gap" data-gs-scope="chat-stream" data-gs-part="gap">
            {copy['chat-stream.gap'](gap)}
          </p>
        ) : null}
        {children}
      </div>

      {/* Over the stream at its foot, never a row of it: a control that pushed
          the last message up would move the thing the player is reading. */}
      {!following && onResume && !atmosphere ? (
        <button
          type="button"
          className="gs-chat-stream__resume gs-action-type gs-pressable"
          data-gs-scope="chat-stream" data-gs-part="control"
          data-gs-count={newCount}
          onClick={onResume}
        >
          <span className="gs-chat-stream__resume-glyph" aria-hidden="true">
            <ChevronGlyph direction="down" />
          </span>
          {copy['chat-stream.resume'](newCount)}
        </button>
      ) : null}

      {paused ? (
        <p className="gs-chat-stream__note" data-gs-scope="chat-stream" data-gs-part="note">
          {copy['chat-stream.hostPaused']}
        </p>
      ) : null}
    </div>
  )
}

/* ChatStream. Every value comes from a token; nothing here is a literal colour.

   Specimen 6b draws the room at 390 by 600 and 6j draws the four ways it
   stops. The frame's height is the host's: this sets none, the same decision
   `stage` made, because only the screen around it knows how tall it is. What
   this owns is that the list is the only thing inside it that scrolls. */

.gs-chat-stream {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  /* Fill whatever the host gave it. A host that gives it nothing gets a frame
     the size of its messages, which is the web page this library is not. */
  block-size: 100%;
}

/* Held at the top, above the scroll, so it does not scroll away. One at a
   time: a second is a second thing to read before the room. */
.gs-chat-stream__pinned {
  flex: none;
  /* Its own foot and a hairline under it, so the room scrolling beneath reads
     as passing under the pinned message rather than colliding with it. */
  padding: var(--gs-space-3) var(--gs-space-inset) var(--gs-space-2);
  border-bottom: var(--gs-stroke-hairline) solid var(--gs-color-edge);
}

/* The one scrolling thing. `justify-content: flex-end` keeps a short room at
   the foot rather than floating it at the top of an empty frame, which is
   where the drawing puts five messages in a 600px card. */
.gs-chat-stream__list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;

  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: var(--gs-space-2);
  padding: var(--gs-space-3) var(--gs-space-inset);
}

/* The break, where messages were left out: one centred line, unowned, the
   same shape as a system message because it is one kind of thing. */
.gs-chat-stream__gap {
  align-self: center;
  margin: 0;
  padding: var(--gs-space-1) var(--gs-space-3);

  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-label-font-weight);

  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

/* Over the stream at the foot, taking 36px of the scene and never a row of
   it. Absolute, so the last message stays where the player left it. */
.gs-chat-stream__resume {
  position: absolute;
  left: 50%;
  bottom: var(--gs-space-3);
  transform: translateX(-50%);
  z-index: 1;

  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
  height: var(--gs-size-control-small);
  padding: 0 var(--gs-space-inset);
  white-space: nowrap;
  cursor: pointer;

  /* The action face, the case and the press gesture come from
     `.gs-action-type` and `.gs-pressable`; only the size is this control's. */
  font-size: var(--gs-type-action-font-size);

  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-raised);
}

.gs-chat-stream__resume:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* Down, to the messages it takes the player to. */
.gs-chat-stream__resume-glyph {
  display: inline-flex;
  font-size: var(--gs-size-icon-utility);
}

/* -- the host froze the room ----------------------------------------------- */

/* Everything already there stays readable at half strength, and the frame is
   the same height paused as live, so nothing jumps when it comes back. */
.gs-chat-stream[data-gs-paused='true'] .gs-chat-stream__list,
.gs-chat-stream[data-gs-paused='true'] .gs-chat-stream__pinned {
  opacity: 0.5;
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-chat-stream__note {
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
  height: var(--gs-size-touch-min);
  margin: 0 var(--gs-space-inset) var(--gs-space-3);
  padding: 0 var(--gs-space-inset);

  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-label-font-weight);

  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

/* -- how the room fits the screen (specimen 6i) -----------------------------

   All three hold the frame still, which is the rule in
   `docs/mobile-game-frame.md`. None of them appends a panel under the round,
   and none of them sets a height: where the stream goes is the host's, and
   `docs/public/stage.md` says which layer each one belongs in.

   `sheet` is the default and carries nothing of its own here, because the
   surface, the scrim and the drag handle belong to the `sheet` component the
   host wraps this in. Writing them again would be a second sheet drawn by a
   stream. */

/* Docked: a fixed band at the foot of the scene, inside the interaction
   layer. It is the only placement that paints a background of its own,
   because it is the only one with an edge against the scene. */
.gs-chat-stream[data-gs-presentation='docked'] {
  background: var(--gs-color-background);
  border-top: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
}

/* Overlay: the last few messages over the scene, oldest faintest, and nothing
   to press. Nothing paints, because anything that did would be a panel over
   the scene and the scene is the point. */
.gs-chat-stream[data-gs-presentation='overlay'] .gs-chat-stream__list {
  overflow: hidden;
  padding-block: 0;
}

.gs-chat-stream[data-gs-presentation='overlay'] .gs-chat-stream__list > :not(:last-child) {
  opacity: 0.65;
}

.gs-chat-stream[data-gs-presentation='overlay'] .gs-chat-stream__list > :first-child:not(:last-child) {
  opacity: 0.35;
}
